function defineLeadPage() {
  var url = document.location.pathname;
  var lead_category;

  if (url == "/oportunidades-pos-barcos") {
    lead_category = "barcos";
  } 
  else if (url == "/oportunidades-pos-motos") {
    lead_category = "motos";
  }
  else if (url == "/oportunidades-pos-caminhoes") {
    lead_category = "caminhões";
  } 
  else if (url == "/oportunidade-pos-carros") {
    lead_category = "carros";
  }

  return lead_category;
}
